scalar = 1.0f;
if (cv_friendlyFire->value != 0.0f) {
    owner_id = -1 - render_overlay_player_index;
} else {
    owner_id = -100;
}

random_offset.x = player->aim.x;
random_offset.y = player->aim.y;
move_delta.x = random_offset.x - player_position->x;
